import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }

// --- SVG Components ---

const MoneyBag = ({ color, size = 100 }: { color: string; size?: number }) => (
  <svg
    width={size}
    height={size}
    viewBox="0 0 100 100"
    style={{ overflow: "visible" }}
  >
    {/* Sack Body */}
    <path
      d="M25 35 C 10 35, 5 95, 50 95 C 95 95, 90 35, 75 35 C 80 25, 60 10, 50 15 C 40 10, 20 25, 25 35 Z"
      fill={color}
    />
    {/* Tie String */}
    <path
      d="M30 35 L 70 35"
      stroke="#fff"
      strokeWidth="3"
      strokeLinecap="round"
    />
    {/* Dollar Sign */}
    <text
      x="50"
      y="75"
      fill="#1a1a1a" // Dark text on gold bag usually looks best, or assume bag is generic color
      fontFamily="Cinzel"
      fontWeight="700"
      fontSize="40"
      textAnchor="middle"
    >
      $
    </text>
  </svg>
);

// --- Main Schema & Component ---



export type ScaleAnimationProps = Record<string, any>;

const ScaleAnimation: React.FC<ScaleAnimationProps> = ({
  backgroundColor = "#1e1e1e",
  transparentBackground = false,
  durationInSeconds = 6,
  scaleColor = "#c0a060", // Gold/Bronze
  bagColor = "#ffd700",   // Gold
  scaleSize = 1,
}) => {
  useFontLoader(["Cinzel"]);
  
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- Layout Constants ---
  const centerX = width / 2;
  const centerY = height * 0.55;
  const beamLength = 500 * scaleSize;
  const panRadius = 80 * scaleSize;
  const panWireLength = 180 * scaleSize;
  
  // --- Animation Timing ---
  
  // Phase: Tipping
  // This drives the scale rotation.
  const pushSpring = spring({
    frame: frame - 15, // Starts earlier now that hand is gone
    fps,
    config: { damping: 20, mass: 2, stiffness: 40 },
  });

  // --- Physics Calculations ---

  // Initial angle: Tipped LEFT (negative angle) because Cash is heavy
  const startAngle = -15 * (Math.PI / 180);
  // Final angle: Tipped RIGHT (positive angle)
  const targetAngle = 15 * (Math.PI / 180);
  
  // Interpolate angle based on pushSpring
  const currentAngle = interpolate(
    pushSpring,
    [0, 1],
    [startAngle, targetAngle],
    { extrapolateRight: "clamp" }
  );

  // Calculate Pan Anchor Points based on current rotation
  // Left Anchor (Bag)
  const leftAnchorX = centerX - (beamLength / 2) * Math.cos(currentAngle);
  const leftAnchorY = centerY - (beamLength / 2) * Math.sin(currentAngle);

  // Right Anchor (Empty)
  const rightAnchorX = centerX + (beamLength / 2) * Math.cos(currentAngle);
  const rightAnchorY = centerY + (beamLength / 2) * Math.sin(currentAngle);

  // Pan Positions (hanging down)
  // Simple pendulum approximation: vertically down from anchor
  const leftPanX = leftAnchorX;
  const leftPanY = leftAnchorY + panWireLength;

  const rightPanX = rightAnchorX;
  const rightPanY = rightAnchorY + panWireLength;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Cinzel" }}>
      
      {/* --- Central Scale Base (Static) --- */}
      <div
        style={{
          position: "absolute",
          left: centerX - 10 * scaleSize,
          top: centerY,
          width: 20 * scaleSize,
          height: 300 * scaleSize,
          backgroundColor: scaleColor,
          borderRadius: 4,
          transform: "translateX(-50%)",
        }}
      >
        {/* Decorative Base Foot */}
        <div 
           style={{
            position: "absolute",
            bottom: 0,
            left: "50%",
            transform: "translateX(-50%)",
            width: 100 * scaleSize,
            height: 20 * scaleSize,
            backgroundColor: scaleColor,
            borderRadius: "4px 4px 0 0"
           }}
        />
      </div>

      {/* --- Rotating Assembly (Beam + Pans) --- */}
      {/* We draw the beam and wires manually using SVG for clean rotation */}
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", top: 0, left: 0, overflow: "visible" }}
      >
        {/* Beam */}
        <line
          x1={leftAnchorX}
          y1={leftAnchorY}
          x2={rightAnchorX}
          y2={rightAnchorY}
          stroke={scaleColor}
          strokeWidth={8 * scaleSize}
          strokeLinecap="round"
        />
        
        {/* Center Pivot Circle */}
        <circle cx={centerX} cy={centerY} r={10 * scaleSize} fill={scaleColor} />

        {/* --- Left Side (Money Bag) --- */}
        {/* Wires */}
        <line
          x1={leftAnchorX}
          y1={leftAnchorY}
          x2={leftPanX - panRadius}
          y2={leftPanY}
          stroke={scaleColor}
          strokeWidth={2}
        />
        <line
          x1={leftAnchorX}
          y1={leftAnchorY}
          x2={leftPanX + panRadius}
          y2={leftPanY}
          stroke={scaleColor}
          strokeWidth={2}
        />
        {/* Pan Bowl */}
        <path
          d={`M ${leftPanX - panRadius} ${leftPanY} A ${panRadius} ${panRadius * 0.4} 0 0 0 ${leftPanX + panRadius} ${leftPanY}`}
          fill="none"
          stroke={scaleColor}
          strokeWidth={4}
        />
         {/* Pan Bottom Fill (Optional opacity) */}
         <path
          d={`M ${leftPanX - panRadius} ${leftPanY} A ${panRadius} ${panRadius * 0.4} 0 0 0 ${leftPanX + panRadius} ${leftPanY}`}
          fill={scaleColor}
          opacity={0.3}
        />

        {/* --- Right Side (Empty) --- */}
        {/* Wires */}
        <line
          x1={rightAnchorX}
          y1={rightAnchorY}
          x2={rightPanX - panRadius}
          y2={rightPanY}
          stroke={scaleColor}
          strokeWidth={2}
        />
        <line
          x1={rightAnchorX}
          y1={rightAnchorY}
          x2={rightPanX + panRadius}
          y2={rightPanY}
          stroke={scaleColor}
          strokeWidth={2}
        />
         {/* Pan Bowl */}
         <path
          d={`M ${rightPanX - panRadius} ${rightPanY} A ${panRadius} ${panRadius * 0.4} 0 0 0 ${rightPanX + panRadius} ${rightPanY}`}
          fill="none"
          stroke={scaleColor}
          strokeWidth={4}
        />
        <path
          d={`M ${rightPanX - panRadius} ${rightPanY} A ${panRadius} ${panRadius * 0.4} 0 0 0 ${rightPanX + panRadius} ${rightPanY}`}
          fill={scaleColor}
          opacity={0.3}
        />
      </svg>

      {/* --- Items on Pans --- */}
      
      {/* Cash Bag (Left Pan) */}
      <div
        style={{
          position: "absolute",
          left: leftPanX,
          top: leftPanY,
          transform: `translate(-50%, -90%) rotate(${-currentAngle * 10}deg)`, // Slight counter-rotation for physics feel
        }}
      >
        <MoneyBag color={bagColor} size={140 * scaleSize} />
      </div>

    </AbsoluteFill>
  );
};

export default ScaleAnimation;